DO $$
DECLARE owner_id uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();company uuid;service uuid:=gen_random_uuid();result jsonb;context jsonb;object_id uuid:=gen_random_uuid();affected integer;
BEGIN
  PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claim.role','service_role',true);PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
  INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(owner_id,'attachment-'||owner_id||'@example.test','{"nome_completo":"Attachment owner","razao_social":"Attachment fixture"}');
  INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(outsider,'attachment-other-'||outsider||'@example.test','{"nome_completo":"Other attachment owner","razao_social":"Other attachment fixture"}');
  SELECT tenant_id INTO company FROM public.profiles WHERE id=owner_id;
  PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','session_id',gen_random_uuid())::text,true);
  PERFORM public.autorizar_dispositivo(gen_random_uuid(),'Attachment fixture');
  INSERT INTO public.servicos(id,tenant_id,nome,created_by) VALUES(service,company,'Attachment service',owner_id);
  PERFORM public.ficha_servico_salvar(service,'corte','{}',0);
  result:=public.anexo_preparar(service,'corte','plano.pdf','application/pdf',2048);
  IF result->>'status'<>'pendente' OR NOT private.attachment_upload_allowed(result->>'caminho') THEN RAISE EXCEPTION 'Upload autorizado não preparado'; END IF;
  IF private.attachment_download_allowed(result->>'caminho') THEN RAISE EXCEPTION 'Arquivo não validado liberado para consulta'; END IF;
  IF jsonb_array_length(public.anexos_ficha_listar(service,'corte')->'itens')<>0 THEN RAISE EXCEPTION 'Lista revelou anexo pendente'; END IF;
  BEGIN PERFORM public.ficha_servico_salvar(service,'corte',jsonb_build_object('plano_corte',result->>'id'),1);RAISE EXCEPTION 'Ficha vinculou anexo pendente';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  -- Metadata fixture only: binary validation is covered by Edge/content tests.
  EXECUTE 'SET LOCAL ROLE authenticated';
  INSERT INTO storage.objects(id,bucket_id,name,metadata) VALUES(object_id,'workforce-private',result->>'caminho','{"size":2048,"mimetype":"application/pdf"}');
  IF EXISTS(SELECT 1 FROM storage.objects WHERE id=object_id) THEN RAISE EXCEPTION 'RLS revelou arquivo pendente'; END IF;
  BEGIN INSERT INTO storage.objects(bucket_id,name) VALUES('workforce-private',company::text||'/'||gen_random_uuid()::text);RAISE EXCEPTION 'RLS aceitou caminho não preparado';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  EXECUTE 'RESET ROLE';
  context:=public.anexo_contexto_validacao((result->>'id')::uuid);
  IF context->>'objeto_id'<>object_id::text THEN RAISE EXCEPTION 'Contexto não vinculou o objeto correto'; END IF;
  IF has_function_privilege('authenticated','public.anexo_confirmar_validacao(uuid,uuid,uuid,uuid,text)','EXECUTE') THEN RAISE EXCEPTION 'Funcionário pode confirmar conteúdo sem servidor'; END IF;
  BEGIN PERFORM public.anexo_confirmar_validacao((result->>'id')::uuid,owner_id,(context->>'sessao_id')::uuid,object_id,'hash-invalido');RAISE EXCEPTION 'Hash inválido aceito';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  PERFORM public.anexo_confirmar_validacao((result->>'id')::uuid,owner_id,(context->>'sessao_id')::uuid,object_id,repeat('a',64));
  PERFORM public.anexo_confirmar_validacao((result->>'id')::uuid,owner_id,(context->>'sessao_id')::uuid,object_id,repeat('a',64));
  IF NOT private.attachment_download_allowed(result->>'caminho') THEN RAISE EXCEPTION 'Arquivo confirmado não foi liberado'; END IF;
  EXECUTE 'SET LOCAL ROLE authenticated';
  IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE id=object_id) THEN RAISE EXCEPTION 'RLS bloqueou arquivo validado autorizado'; END IF;
  UPDATE storage.objects SET metadata='{}' WHERE id=object_id;
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>0 THEN RAISE EXCEPTION 'RLS permitiu sobrescrever anexo'; END IF;
  EXECUTE 'RESET ROLE';
  IF jsonb_array_length(public.anexos_ficha_listar(service,'corte')->'itens')<>1 THEN RAISE EXCEPTION 'Lista não exibiu anexo validado'; END IF;
  PERFORM public.ficha_servico_salvar(service,'corte',jsonb_build_object('plano_corte',result->>'id'),1);
  IF public.ficha_servico_consultar(service,'corte')->'dados'->>'plano_corte'<>result->>'id' THEN RAISE EXCEPTION 'Plano de corte não vinculado'; END IF;
  BEGIN PERFORM public.ficha_servico_salvar(service,'corte',jsonb_build_object('desenho_tecnico',gen_random_uuid()),2);RAISE EXCEPTION 'UUID inventado vinculado';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  IF (SELECT count(*) FROM public.audit_logs WHERE acao='anexo_validado' AND registro_id=result->>'id')<>1 THEN RAISE EXCEPTION 'Validação repetida duplicou auditoria'; END IF;
  BEGIN PERFORM public.anexo_confirmar_validacao((result->>'id')::uuid,owner_id,(context->>'sessao_id')::uuid,object_id,repeat('b',64));RAISE EXCEPTION 'Hash validado foi substituído';EXCEPTION WHEN object_not_in_prerequisite_state THEN NULL;END;
  IF private.attachment_upload_allowed(company::text||'/'||gen_random_uuid()::text) THEN RAISE EXCEPTION 'Caminho inventado autorizado'; END IF;
  IF (SELECT public FROM storage.buckets WHERE id='workforce-private') THEN RAISE EXCEPTION 'Bucket público'; END IF;
  BEGIN PERFORM public.anexo_preparar(service,'corte','../arquivo.pdf','application/pdf',10);RAISE EXCEPTION 'Nome de caminho aceito';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.anexo_preparar(service,'corte','arquivo.html','text/html',10);RAISE EXCEPTION 'HTML aceito';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.anexo_preparar(service,'corte','grande.pdf','application/pdf',10485761);RAISE EXCEPTION 'Tamanho acima do limite aceito';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.anexo_preparar(gen_random_uuid(),'corte','arquivo.pdf','application/pdf',10);RAISE EXCEPTION 'Serviço inventado aceito';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  IF has_table_privilege('authenticated','private.workforce_attachments','UPDATE') THEN RAISE EXCEPTION 'Metadados de anexos expostos'; END IF;
  PERFORM set_config('request.jwt.claim.sub',outsider::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated','session_id',gen_random_uuid())::text,true);
  PERFORM public.autorizar_dispositivo(gen_random_uuid(),'Other attachment fixture');
  EXECUTE 'SET LOCAL ROLE authenticated';
  IF EXISTS(SELECT 1 FROM storage.objects WHERE id=object_id) THEN RAISE EXCEPTION 'Storage vazou arquivo entre empresas'; END IF;
  EXECUTE 'RESET ROLE';
  BEGIN PERFORM public.anexos_ficha_listar(service,'corte');RAISE EXCEPTION 'Lista de anexos vazou entre empresas';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.anexo_contexto_validacao((result->>'id')::uuid);RAISE EXCEPTION 'Contexto vazou entre empresas';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END;
$$;
SELECT 'PASS: preparação privada, limites, caminhos e bloqueio de arquivo não validado' AS result;
